mutations.before:
if (!res.ok) {
  throw new TemplatesApiError(errorFrom(data, `Request failed (HTTP ${res.status})`), res.status);
}

const known = latest.get(template.id);
if (known === undefined || template.version > known.version) {
  latest.set(template.id, template);
}

mutations.after:
const known = latest.get(template.id);
if (known === undefined) {
  latest.set(template.id, template);
}

mutations.before:
const candidate = {
  id: template.id,
  version: template.version,

) : (
  <TemplateDetail
    template={shown}
    // `shown` is only defined when `entries` is, so the history is read
    // from the loaded list — never a fetch, and never a fallback that no
    // state can reach.
    versions={versionsOf(entries as CreativeTemplate[], shown.id)}
    briefs={briefs}
    pinned={pinnable}
    canRender={pinnable !== null && product !== undefined}
    frame={frame}
    rendering={rendering}
    renderFailed={renderFailed}
    onBack={back}
    backRef={(node) => {
      if (node === null || !pendingFocusBack.current) return;
      pendingFocusBack.current = false;
      node.focus();
    }}
    onClose={closeTemplateLibrary}
    onSelectVersion={(version) => openDetail({ ...shown, version })}
    onRenderPreview={renderPreview}
    onUseTemplate={useTemplate}
  />
)}

mutations.after:
